INSERT INTO `kp_topic_quiz` (`id`,`topic_id`,`question_type`,`question`,`options`,`answer`,`sort`,`create_time`,`update_time`,`is_delete`) VALUES (1,33,'single','根据这条知识，MyBatis 报 `Cannot determine value type from string` 的本质是什么？','["没有无参构造时，试图按顺序用有参构造“拼”对象，结果数据顺序或类型对不上，导致转换失败", "有无参构造时，试图按顺序用有参构造“拼”对象，结果数据顺序或类型对不上，导致转换失败", "没有无参构造时，试图按顺序用有参构造“拼”对象，结果数据顺序和类型都对得上，导致转换失败", "没有无参构造时，不按顺序用有参构造“拼”对象，结果数据顺序或类型对不上，导致转换失败"]','0',0,STR_TO_DATE('2026-10-07 03:02:41', '%Y-%m-%d %H:%i:%s'),STR_TO_DATE('2026-10-13 16:32:43', '%Y-%m-%d %H:%i:%s'),1);
INSERT INTO `kp_topic_quiz` (`id`,`topic_id`,`question_type`,`question`,`options`,`answer`,`sort`,`create_time`,`update_time`,`is_delete`) VALUES (2,33,'single','根据这条知识，MyBatis 试图按顺序用有参构造“拼”对象的前提是什么？','["有无参构造", "没有无参构造", "没有无参构造且数据顺序和类型都对得上", "没有无参构造且数据顺序或类型对不上"]','1',1,STR_TO_DATE('2026-10-07 03:02:41', '%Y-%m-%d %H:%i:%s'),STR_TO_DATE('2026-10-13 16:32:43', '%Y-%m-%d %H:%i:%s'),1);
INSERT INTO `kp_topic_quiz` (`id`,`topic_id`,`question_type`,`question`,`options`,`answer`,`sort`,`create_time`,`update_time`,`is_delete`) VALUES (3,33,'single','根据这条知识，转换失败的直接相关因素是什么？','["数据顺序和类型都对得上", "数据顺序或类型对不上", "有无参构造且数据顺序或类型对不上", "没有无参构造且数据顺序和类型都对得上"]','1',2,STR_TO_DATE('2026-10-07 03:02:41', '%Y-%m-%d %H:%i:%s'),STR_TO_DATE('2026-10-13 16:32:43', '%Y-%m-%d %H:%i:%s'),1);
INSERT INTO `kp_topic_quiz` (`id`,`topic_id`,`question_type`,`question`,`options`,`answer`,`sort`,`create_time`,`update_time`,`is_delete`) VALUES (4,36,'single','关于 `WHERE is_delete != 1` 的作用，以下说法正确的是？','["会查出 `is_delete` 为 `0` 和 `null` 的所有行", "只会查出 `is_delete` 为 `0` 的行，`null` 会被过滤", "只会查出 `is_delete` 为 `1` 的行", "会查出 `is_delete` 不为 `1` 的所有行，包括 `null`"]','1',0,STR_TO_DATE('2026-10-07 03:15:06', '%Y-%m-%d %H:%i:%s'),STR_TO_DATE('2026-10-13 16:32:43', '%Y-%m-%d %H:%i:%s'),1);
INSERT INTO `kp_topic_quiz` (`id`,`topic_id`,`question_type`,`question`,`options`,`answer`,`sort`,`create_time`,`update_time`,`is_delete`) VALUES (5,36,'single','为什么 `is_delete` 为 `null` 的行不会被 `WHERE is_delete != 1` 查出？','["因为 `null` 等于 `1`", "因为 `null` 不等于 `1` 的结果为 `true`", "因为 SQL 中 `NULL` 与任何值比较结果都是 `NULL`，`WHERE` 会过滤掉 `NULL`", "因为 `is_delete` 不能为 `null`"]','2',1,STR_TO_DATE('2026-10-07 03:15:06', '%Y-%m-%d %H:%i:%s'),STR_TO_DATE('2026-10-13 16:32:43', '%Y-%m-%d %H:%i:%s'),1);
INSERT INTO `kp_topic_quiz` (`id`,`topic_id`,`question_type`,`question`,`options`,`answer`,`sort`,`create_time`,`update_time`,`is_delete`) VALUES (6,36,'single','要查出所有未删除的数据（包括 `is_delete` 为 `null` 的行），以下哪个 `WHERE` 条件是正确的？','["`WHERE is_delete != 1`", "`WHERE is_delete = 0`", "`WHERE is_delete IS NULL OR is_delete != 1`", "`WHERE is_delete IS NOT NULL`"]','2',2,STR_TO_DATE('2026-10-07 03:15:06', '%Y-%m-%d %H:%i:%s'),STR_TO_DATE('2026-10-13 16:32:43', '%Y-%m-%d %H:%i:%s'),1);
INSERT INTO `kp_topic_quiz` (`id`,`topic_id`,`question_type`,`question`,`options`,`answer`,`sort`,`create_time`,`update_time`,`is_delete`) VALUES (56,78,'single','关于 Kubernetes Deployment 的存储能力，下列哪项说法正确？','["可使用 volumeClaimTemplates 为每个 Pod 自动创建独立 PVC", "通常需要挂载 hostPath 读取节点本地日志", "配合普通 PVC 时，不支持为每个 Pod 自动生成独立 PVC", "每个 Pod 都有固定有序名称和稳定网络标识"]','2',0,STR_TO_DATE('2026-10-16 18:06:28', '%Y-%m-%d %H:%i:%s'),STR_TO_DATE('2026-10-16 18:06:28', '%Y-%m-%d %H:%i:%s'),0);
INSERT INTO `kp_topic_quiz` (`id`,`topic_id`,`question_type`,`question`,`options`,`answer`,`sort`,`create_time`,`update_time`,`is_delete`) VALUES (57,78,'multiple','关于 Kubernetes StatefulSet，下列哪些说法正确？','["Pod 重建后名称和 IP 都会改变，副本之间完全对等", "通过 volumeClaimTemplates 可为每个 Pod 自动生成独立 PVC", "配合 Headless Service，Pod 可获得固定域名", "扩缩容时所有 Pod 并行启动或销毁，无顺序要求"]','[1,2]',1,STR_TO_DATE('2026-10-16 18:06:28', '%Y-%m-%d %H:%i:%s'),STR_TO_DATE('2026-10-16 18:06:28', '%Y-%m-%d %H:%i:%s'),0);
INSERT INTO `kp_topic_quiz` (`id`,`topic_id`,`question_type`,`question`,`options`,`answer`,`sort`,`create_time`,`update_time`,`is_delete`) VALUES (58,78,'essay','DaemonSet 如何随集群节点变化管理 Pod？它是否使用 replicas 控制实例数？','[]','每个（或指定）节点运行且仅运行一个 Pod；不管理 replicas，节点增减时自动创建或销毁 Pod',2,STR_TO_DATE('2026-10-16 18:06:28', '%Y-%m-%d %H:%i:%s'),STR_TO_DATE('2026-10-16 18:06:28', '%Y-%m-%d %H:%i:%s'),0);
INSERT INTO `kp_topic_quiz` (`id`,`topic_id`,`question_type`,`question`,`options`,`answer`,`sort`,`create_time`,`update_time`,`is_delete`) VALUES (59,78,'single','要让 StatefulSet 的每个 Pod 拥有固定、可解析的域名（形如 `es-0.es-svc.ns.svc.cluster.local`），需要为它配套哪种 Service？','["普通 ClusterIP Service，会自动为每个 Pod 分配固定域名", "Headless Service，即 `clusterIP: None` 的 Service", "NodePort Service，通过节点端口暴露每个 Pod", "Ingress，由 Ingress 控制器为每个 Pod 生成域名"]','1',3,STR_TO_DATE('2026-10-16 18:06:28', '%Y-%m-%d %H:%i:%s'),STR_TO_DATE('2026-10-16 18:06:28', '%Y-%m-%d %H:%i:%s'),0);
INSERT INTO `kp_topic_quiz` (`id`,`topic_id`,`question_type`,`question`,`options`,`answer`,`sort`,`create_time`,`update_time`,`is_delete`) VALUES (60,78,'multiple','关于 DaemonSet 的运行方式，下列说法正确的有？','["它不使用 replicas 控制实例数，Pod 数量随集群节点数量变化", "集群新增一个节点时，会在该新节点上自动创建 Pod", "某个节点下线时，该节点上由 DaemonSet 管理的 Pod 会被自动销毁", "把它的 replicas 设为 3，就能让 Pod 只在 3 个指定节点上运行"]','[0,1,2]',4,STR_TO_DATE('2026-10-16 18:06:28', '%Y-%m-%d %H:%i:%s'),STR_TO_DATE('2026-10-16 18:06:28', '%Y-%m-%d %H:%i:%s'),0);
INSERT INTO `kp_topic_quiz` (`id`,`topic_id`,`question_type`,`question`,`options`,`answer`,`sort`,`create_time`,`update_time`,`is_delete`) VALUES (61,78,'essay','Deployment 和 StatefulSet 在持久存储上的关键区别是什么？','[]','Deployment 只能共享 PVC，不能给每个 Pod 自动生成独立 PVC；StatefulSet 通过 volumeClaimTemplates 为每个 Pod 生成自己的 PVC',5,STR_TO_DATE('2026-10-16 18:06:28', '%Y-%m-%d %H:%i:%s'),STR_TO_DATE('2026-10-16 18:06:28', '%Y-%m-%d %H:%i:%s'),0);
INSERT INTO `kp_topic_quiz` (`id`,`topic_id`,`question_type`,`question`,`options`,`answer`,`sort`,`create_time`,`update_time`,`is_delete`) VALUES (62,82,'single','TCP 三次握手中，服务器在第二次握手时发送的报文包含哪些标志位？','["只含 SYN", "只含 ACK", "同时含 SYN 和 ACK", "同时含 FIN 和 ACK"]','2',0,STR_TO_DATE('2026-10-16 18:06:58', '%Y-%m-%d %H:%i:%s'),STR_TO_DATE('2026-10-16 18:06:58', '%Y-%m-%d %H:%i:%s'),0);
INSERT INTO `kp_topic_quiz` (`id`,`topic_id`,`question_type`,`question`,`options`,`answer`,`sort`,`create_time`,`update_time`,`is_delete`) VALUES (63,82,'multiple','关于 TCP 三次握手，下列说法正确的有？','["第一次握手客户端发送 SYN 报文，随后进入 SYN_SENT 状态", "服务器收到 SYN 后回复 SYN+ACK 报文", "服务器发出 SYN+ACK 后就认为连接已经建立", "第三次握手客户端发送 ACK，用于确认服务器的 SYN"]','[0,1,3]',1,STR_TO_DATE('2026-10-16 18:06:58', '%Y-%m-%d %H:%i:%s'),STR_TO_DATE('2026-10-16 18:06:58', '%Y-%m-%d %H:%i:%s'),0);
INSERT INTO `kp_topic_quiz` (`id`,`topic_id`,`question_type`,`question`,`options`,`answer`,`sort`,`create_time`,`update_time`,`is_delete`) VALUES (64,82,'essay','TCP 建立连接为什么需要三次握手，而不是两次？','[]','防止失效的旧连接请求到达服务器，白占资源；确认双方收发能力并同步初始序列号',2,STR_TO_DATE('2026-10-16 18:06:58', '%Y-%m-%d %H:%i:%s'),STR_TO_DATE('2026-10-16 18:06:58', '%Y-%m-%d %H:%i:%s'),0);
INSERT INTO `kp_topic_quiz` (`id`,`topic_id`,`question_type`,`question`,`options`,`answer`,`sort`,`create_time`,`update_time`,`is_delete`) VALUES (65,79,'single','在 Windows 11 中，按 Win + R 输入 cmd 后，要以管理员身份打开命令提示符，应按哪个组合键？','["Ctrl + Enter", "Ctrl + Shift + Enter", "Shift + Enter", "Alt + Enter"]','1',0,STR_TO_DATE('2026-10-16 19:47:53', '%Y-%m-%d %H:%i:%s'),STR_TO_DATE('2026-10-16 19:47:53', '%Y-%m-%d %H:%i:%s'),0);
INSERT INTO `kp_topic_quiz` (`id`,`topic_id`,`question_type`,`question`,`options`,`answer`,`sort`,`create_time`,`update_time`,`is_delete`) VALUES (66,79,'multiple','一台 Windows 11 电脑出现「DNS 服务器未响应」，下列哪些说法是正确的？','["该问题通常与网络配置、缓存或第三方软件冲突有关", "刷新 DNS 缓存可清除错误的 DNS 缓存并重置网络协议", "执行完相关修复命令后重启电脑，有助于检查网络是否恢复正常", "这类问题只能通过重装系统解决"]','[0,1,2]',1,STR_TO_DATE('2026-10-16 19:47:53', '%Y-%m-%d %H:%i:%s'),STR_TO_DATE('2026-10-16 19:47:53', '%Y-%m-%d %H:%i:%s'),0);
INSERT INTO `kp_topic_quiz` (`id`,`topic_id`,`question_type`,`question`,`options`,`answer`,`sort`,`create_time`,`update_time`,`is_delete`) VALUES (67,79,'blank','在 Windows 11 的命令提示符中，用于刷新 DNS 缓存的命令是 ipconfig /______。','[]','flushdns',2,STR_TO_DATE('2026-10-16 19:47:53', '%Y-%m-%d %H:%i:%s'),STR_TO_DATE('2026-10-16 19:47:53', '%Y-%m-%d %H:%i:%s'),0);
