INSERT INTO `kp_topic_quiz` (`id`,`topic_id`,`question_type`,`question`,`options`,`answer`,`sort`,`create_time`,`update_time`,`is_delete`) VALUES (89,77,'multiple','要查看测试影像库里的镜像文件，以下哪些做法成立？','["用 imgstore 账号通过 SSH 登录 135.72.40.105", "从本机直连时使用 2222 端口的 135.64.132.201", "登录后在 `/app/imgstore/jq_img-for-test` 目录下查看", "必须先以 root 登录 135.72.40.105 才能访问影像库"]','[0,1,2]',1,STR_TO_DATE('2026-10-21 17:46:13', '%Y-%m-%d %H:%i:%s'),STR_TO_DATE('2026-10-21 17:46:13', '%Y-%m-%d %H:%i:%s'),0);
INSERT INTO `kp_topic_quiz` (`id`,`topic_id`,`question_type`,`question`,`options`,`answer`,`sort`,`create_time`,`update_time`,`is_delete`) VALUES (90,77,'blank','访问 CRM 测试环境 `https://crm.dx.com:8080/sso/login` 之前，需要在 hosts 中把 crm.dx.com 指向哪个 IP？','[]','135.64.133.43',2,STR_TO_DATE('2026-10-21 17:46:13', '%Y-%m-%d %H:%i:%s'),STR_TO_DATE('2026-10-21 17:46:13', '%Y-%m-%d %H:%i:%s'),0);
