INSERT INTO `kp_topic_quiz` (`id`,`topic_id`,`question_type`,`question`,`options`,`answer`,`sort`,`create_time`,`update_time`,`is_delete`) VALUES (92,77,'multiple','关于影像库（imgstore）测试环境的访问方式与路径，下列说法成立的有哪些？','["可以直接用 `ssh imgstore@135.72.40.105` 登录影像库主机", "从本机登录时，需显式指定 2222 端口，登录到 135.64.132.201 上的 imgstore 账户", "影像库的测试目录是 `/app/imgstore/jq_img-for-test`", "影像库与 CRM 门户部署在同一台主机 135.64.133.43 上"]','[0,1,2]',4,STR_TO_DATE('2026-10-21 17:46:14', '%Y-%m-%d %H:%i:%s'),STR_TO_DATE('2026-10-21 17:46:14', '%Y-%m-%d %H:%i:%s'),0);
INSERT INTO `kp_topic_quiz` (`id`,`topic_id`,`question_type`,`question`,`options`,`answer`,`sort`,`create_time`,`update_time`,`is_delete`) VALUES (93,77,'essay','portalcenter-openapi-server 的门户数据库数据源是如何加载的？其中 autoconfig.xx 项加载的是什么？','[]','通过 cloudb.jdbc.ds.xml 动态加载数据源；autoconfig.xx 加载 disconf 远程的 autoconfig.properties；默认配置的就是门户数据库',5,STR_TO_DATE('2026-10-21 17:46:14', '%Y-%m-%d %H:%i:%s'),STR_TO_DATE('2026-10-21 17:46:14', '%Y-%m-%d %H:%i:%s'),0);
INSERT INTO `kp_topic_quiz` (`id`,`topic_id`,`question_type`,`question`,`options`,`answer`,`sort`,`create_time`,`update_time`,`is_delete`) VALUES (94,89,'single','需要读多写少的并发场景，最适合使用下列哪个 `List` 实现类？','["`ArrayList`", "`LinkedList`", "`Vector`", "`CopyOnWriteArrayList`"]','3',0,STR_TO_DATE('2026-10-21 12:25:23', '%Y-%m-%d %H:%i:%s'),STR_TO_DATE('2026-10-21 12:25:23', '%Y-%m-%d %H:%i:%s'),0);
INSERT INTO `kp_topic_quiz` (`id`,`topic_id`,`question_type`,`question`,`options`,`answer`,`sort`,`create_time`,`update_time`,`is_delete`) VALUES (95,89,'multiple','关于 `List` 接口要求实现类遵守的约定，下列说法正确的有哪些？','["迭代顺序必须与插入顺序一致", "两个 `List` 相等，要求元素相同且顺序相同", "`List` 允许存储重复元素", "`List` 的 `hashCode` 只由元素决定，与元素顺序无关"]','[0,1,2]',1,STR_TO_DATE('2026-10-21 12:25:23', '%Y-%m-%d %H:%i:%s'),STR_TO_DATE('2026-10-21 12:25:23', '%Y-%m-%d %H:%i:%s'),0);
INSERT INTO `kp_topic_quiz` (`id`,`topic_id`,`question_type`,`question`,`options`,`answer`,`sort`,`create_time`,`update_time`,`is_delete`) VALUES (96,89,'essay','`List` 作为有序序列，区别于 `Set` 的关键特性有哪些？','[]','有序：迭代顺序与插入顺序一致；可按整数索引访问元素；允许存储重复元素',2,STR_TO_DATE('2026-10-21 12:25:23', '%Y-%m-%d %H:%i:%s'),STR_TO_DATE('2026-10-21 12:25:23', '%Y-%m-%d %H:%i:%s'),0);
